Here's a C++ program that generates the Fibonacci sequence using a recursive function:

```cpp
#include <iostream>
#include <string>
#include <sstream>

using namespace std;

int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int first, second, num_elements;

    cout << "Enter the first two integers of the Fibonacci sequence: ";
    getline(cin, input);

    istringstream iss(input);
    iss >> first >> second;

    if (first < 0 || second < 0) {
        cerr << "Error: Both integers must be non-negative." << endl;
        return 1;
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> num_elements;

    if (num_elements < 0) {
        cerr << "Error: The number of sequence elements must be non-negative." << endl;
        return 1;
    }

    int sequence[num_elements];
    sequence[0] = first;
    sequence[1] = second;

    for (int i = 2; i < num_elements; i++) {
        sequence[i] = fibonacci(i, sequence[i - 1], sequence[i - 2]);
    }

    cout << "The Fibonacci sequence up to " << num_elements << " elements:" << endl;
    for (int i = 0; i < num_elements; i++) {
        cout << sequence[i] << ", ";
    }

    return 0;
}
```

