Here's a JavaScript function that takes a string variable in dot notation and returns all entries in an object where the nested key value matches the string key:

```javascript
function getNestedEntry(obj, key) {
  const keys = key.split(".");
  let currentObj = obj;

  for (const key of keys) {
    if (!currentObj.hasOwnProperty(key)) {
      return null;
    }
    currentObj = currentObj[key];
  }

  return currentObj;
}

// Example usage
const obj = {
  a: {
    b: {
      c: "value",
    },
  },
};

const key = "a.b.c";
const result = getNestedEntry(obj, key);
console.log(result); // Output: "value"
```

