Here's a simple Go program that takes the name of a Go source file and the name of a struct as input, parses the struct, and generates an AVRO schema for it. The generated schema will be written to a file named `struct.avsc`.

```go
package main

import (
	"fmt"
	"io/ioutil"
	"regexp"
	"strings"

	"github.com/apache/avro/schema"
)

func main() {
	filePath := "path/to/your/go/source/file.go"
	structName := "YourStructName"

	content, err := ioutil.ReadFile(filePath)
	if err != nil {
		fmt.Println("Error reading file:", err)
		return
	}

	re := regexp.MustCompile(`type (\w+) struct {`)
	matches := re.FindStringSubmatch(string(content))
	if len(matches) != 2 {
		fmt.Println("Unable to find struct definition in the file.")
		return
	}

	structType := matches[1]

	fields := make([]schema.Field, 0)

	// Parse the struct fields
	for _, field := range strings.Split(string(content), "\n") {
		if strings.HasPrefix(field, fmt.Sprintf("%s ", structType)) {
			field = strings.TrimSpace(field)
			parts := strings.SplitN(field, " ", 2)
			name := parts[0]
			typeStr := parts[1]

			fields = append(fields, schema.Field{
				Name:  name,
				Type:  schema.ParseType(typeStr),
			})
		}
	}

	schemaDef := schema.Schema{
		Name:  structName,
		Fields: fields,
	}

	err = ioutil.WriteFile("struct.avsc", []byte(schemaDef.ToString()), 0644)
