  return (
    <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
      <Text>Welcome to my app!</Text>
    </View>
  );
};

export default App;
```
Replace `'your_access_token'` and `'your_refresh_token'` with the actual access token and refresh token you received from Facebook.

