Here's a simple React utility that removes widows from text. It uses the `string-width` library to measure the width of a string and adjusts the line breaks accordingly.

```javascript
import React, { useState } from 'react';
import stringWidth from 'string-width';

const RemoveWidows = ({ text }) => {
  const [lines, setLines] = useState([]);

  const handleTextChange = (event) => {
    const newText = event.target.value;
    const linesArray = newText.split('\n');

    const adjustedLines = linesArray.map((line) => {
      const width = stringWidth(line);
      if (width > 80) {
        return line.replace(/\b\w{1,}(\s*)/g, (match, word, space) => {
          const remainingSpace = 80 - width;
          const truncatedWord = match.slice(0, -remainingSpace);
          return `${truncatedWord} ${space}`;
        });
      }
      return line;
    });

    setLines(adjustedLines);
  };

  return (
    <div>
      <textarea value={text} onChange={handleTextChange} />
      <ul>
        {lines.map((line, index) => (
          <li key={index}>{line}</li>
        ))}
      </ul>
    </div>
  );
};

export default RemoveWidows;
```

